CREATE TABLE marketplace_listings(`id` bigint  UNSIGNED PRIMARY KEY AUTO_INCREMENT,`created_at` timestamp  DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` timestamp  DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP NOT NULL,`enable` TINYINT(1)  NOT NULL  DEFAULT 1 ,`farm_id` bigint  NOT NULL,`farmer_id` bigint  NOT NULL,`crop_type` varchar(255)  NOT NULL,`crop_variety` varchar(255)  NULL,`expected_harvest_date` date  NOT NULL,`estimated_quantity` INT  NOT NULL COMMENT 'Quantity in kg',`available_quantity` INT  NULL COMMENT 'Available quantity for booking in kg (defaults to estimated_quantity)',`quality_grade` varchar(255)  NULL COMMENT 'A, B, C grade prediction',`location_state` varchar(255)  NOT NULL,`location_district` varchar(255)  NOT NULL,`farmer_contact_phone` varchar(255)  NULL,`farmer_contact_email` varchar(255)  NULL,`status` varchar(255)  DEFAULT 'active' COMMENT 'active, booked, harvested, cancelled',`delivery_latitude` DECIMAL(10,8)  NULL COMMENT 'Delivery location GPS latitude (optional)',`delivery_longitude` DECIMAL(11,8)  NULL COMMENT 'Delivery location GPS longitude (optional)',`delivery_pincode` varchar(10)  NULL COMMENT 'Delivery location postal code',`delivery_village` varchar(100)  NULL COMMENT 'Delivery location village/VPO',`delivery_address_line` varchar(255)  NULL COMMENT 'Full delivery address',`embedding` vector(384)  NULL COMMENT 'Vector embedding for similarity matching (384 dimensions)',`embedding_cache_key` varchar(255)  NULL COMMENT 'Cache key for embedding to avoid regeneration',`price_per_unit` DECIMAL(10,2)  NULL COMMENT 'Price per kg in INR')ENGINE = InnoDB AUTO_INCREMENT = 1 DEFAULT CHARSET = utf8;